package com.hau.question.application.service;
import com.hau.question.application.port.out.*; import com.hau.question.domain.model.*; import com.hau.question.infrastructure.rabbitmq.AiGenerationPayload; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AiQuestionImportService {private final QuestionRepository questions;private final ProcessedEventRepository events;private final Clock clock;public AiQuestionImportService(QuestionRepository q,ProcessedEventRepository e,Clock c){questions=q;events=e;clock=c;}
 @Transactional public int importCompleted(UUID eventId,AiGenerationPayload p){if(events.exists(eventId))return 0;int count=0;for(var item:p.questions()){String source=p.jobId()+":"+item.sourceId();if(questions.existsByAiSourceId(source))continue;var opts=item.options().stream().map(o->new QuestionOption(UUID.randomUUID(),o.label(),o.content(),o.imageUrl(),o.storageKey(),o.correct(),o.sortOrder())).toList();questions.save(Question.create(UUID.randomUUID(),p.facultyId(),p.subjectId(),p.chapterId(),p.topicId(),item.content(),item.imageUrl(),item.storageKey(),item.type(),item.difficulty(),QuestionSource.AI,source,p.requestedBy(),opts,Instant.now(clock)));count++;}events.record(eventId,"AI_GENERATION_COMPLETED");return count;}}
